import{h}from"@stencil/core";import{newSpecPage}from"@stencil/core/testing";import{ScLineItemTax}from"../sc-line-item-tax";describe("sc-line-item-tax",(()=>{it("renders",(async()=>{const t=await newSpecPage({components:[ScLineItemTax],html:"<sc-line-item-tax></sc-line-item-tax>"});expect(t.root).toMatchSnapshot()})),it("renders one row per tax breakdown entry",(async()=>{const t=(await newSpecPage({components:[ScLineItemTax],template:()=>h("sc-line-item-tax",{order:{tax_status:"calculated",tax_amount:1200,tax_exclusive_amount:1200,tax_inclusive_amount:0,tax_label:"Tax",tax_breakdown:[{tax_rate:5,tax_label:"GST",taxable_amount:1e4,tax_amount:500,tax_display_amount:"$5.00",taxable_display_amount:"$100.00"},{tax_rate:7,tax_label:"PST",taxable_amount:4e3,tax_amount:700,tax_display_amount:"$7.00",taxable_display_amount:"$40.00"}]}})})).root.shadowRoot.querySelectorAll("sc-line-item");expect(t).toHaveLength(2),expect(t[0].querySelector('[slot="description"]').textContent).toBe("Tax GST (5% on $100.00)"),expect(t[0].querySelector('[slot="price"]').textContent).toBe("$5.00"),expect(t[1].querySelector('[slot="description"]').textContent).toBe("Tax PST (7% on $40.00)"),expect(t[1].querySelector('[slot="price"]').textContent).toBe("$7.00")})),it("keeps a single breakdown row plain",(async()=>{const t=(await newSpecPage({components:[ScLineItemTax],template:()=>h("sc-line-item-tax",{order:{tax_status:"calculated",tax_amount:500,tax_exclusive_amount:500,tax_inclusive_amount:0,tax_label:"GST",tax_breakdown:[{tax_rate:5,tax_label:"GST",taxable_amount:1e4,tax_amount:500,tax_display_amount:"$5.00",taxable_display_amount:"$100.00"}]}})})).root.shadowRoot.querySelectorAll("sc-line-item");expect(t).toHaveLength(1),expect(t[0].querySelector('[slot="description"]').textContent).toBe("Tax GST")})),it("falls back to the single aggregate row without a breakdown",(async()=>{const t=(await newSpecPage({components:[ScLineItemTax],template:()=>h("sc-line-item-tax",{order:{tax_status:"estimated",tax_amount:500,tax_exclusive_amount:500,tax_inclusive_amount:0,tax_label:"GST",tax_display_amount:"$5.00"}})})).root.shadowRoot.querySelectorAll("sc-line-item");expect(t).toHaveLength(1),expect(t[0].querySelector('[slot="description"]').textContent).toBe("Tax Estimated GST"),expect(t[0].querySelector('[slot="price"]').textContent).toBe("$5.00")})),it("marks rows as included for inclusive tax",(async()=>{const t=(await newSpecPage({components:[ScLineItemTax],template:()=>h("sc-line-item-tax",{order:{tax_status:"calculated",tax_amount:500,tax_exclusive_amount:0,tax_inclusive_amount:500,tax_label:"VAT",tax_display_amount:"$5.00"}})})).root.shadowRoot.querySelector("sc-line-item");expect(t.querySelector('[slot="price"]')).toBeNull(),expect(t.querySelector('[slot="price-description"]').textContent).toBe("($5.00 included)")}))}));